import{_ as a,c as r,o as t,a2 as s}from"./chunks/framework.mqLGQ42V.js";const u=JSON.parse('{"title":"形状与路径概览 (Shapes and Paths Overview) - Rive 编辑器","description":"基础概念 (Fundamentals) Rive 允许你使用程序化形状 (Procedural Shapes) 或自定义形状来创建、编辑和制作矢量图形动画。这些图形结合了“形状层 (Shape layer)”和“路径层 (Path layer)”来定义，Rive 开放了这些层级，以便在设计和动...","frontmatter":{"title":"形状与路径概览 (Shapes and Paths Overview) - Rive 编辑器","description":"基础概念 (Fundamentals) Rive 允许你使用程序化形状 (Procedural Shapes) 或自定义形状来创建、编辑和制作矢量图形动画。这些图形结合了“形状层 (Shape layer)”和“路径层 (Path layer)”来定义，Rive 开放了这些层级，以便在设计和动...","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 基础概念, 形状与路径概览"}]]},"headers":[],"relativePath":"editor/fundamentals/shapes-and-paths.md","filePath":"editor/fundamentals/shapes-and-paths.md","lastUpdated":1774867914000}'),o={name:"editor/fundamentals/shapes-and-paths.md"};function h(p,e,l,n,d,i){return t(),r("div",null,[...e[0]||(e[0]=[s('<p>基础概念 (Fundamentals)</p><h1 id="形状与路径概览-shapes-and-paths-overview" tabindex="-1">形状与路径概览 (Shapes and Paths Overview) <a class="header-anchor" href="#形状与路径概览-shapes-and-paths-overview" aria-label="Permalink to &quot;形状与路径概览 (Shapes and Paths Overview)&quot;">​</a></h1><p>Rive 允许你使用程序化形状 (Procedural Shapes) 或自定义形状来创建、编辑和制作矢量图形动画。这些图形结合了“形状层 (Shape layer)”和“路径层 (Path layer)”来定义，Rive 开放了这些层级，以便在设计和动画制作中为你提供更大的灵活性和控制力。</p><p>要了解有关形状层和路径层的更多信息，请观看我们的视频或阅读下文。</p><h2 id="​-形状层-shape-layer" tabindex="-1"><a href="#shape-layer">​</a> 形状层 (Shape layer) <a class="header-anchor" href="#​-形状层-shape-layer" aria-label="Permalink to &quot;[​](#shape-layer) 形状层 (Shape layer)&quot;">​</a></h2><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 形状层示例) Rive 中的矢量图形是在形状层上渲染的。形状层通过允许你自定义“填充 (Fill)”和“描边 (Stroke)”来定义形状的样式。 <em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 填充与描边)</p></blockquote><h2 id="​-路径层-path-layer" tabindex="-1"><a href="#path-layer">​</a> 路径层 (Path layer) <a class="header-anchor" href="#​-路径层-path-layer" aria-label="Permalink to &quot;[​](#path-layer) 路径层 (Path layer)&quot;">​</a></h2><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 路径层示例) 矢量图形的实际轮廓是由一个或多个路径定义的。在 Rive 的层级面板中展开一个形状层，即可查看到它正在使用的路径。 <em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 移动路径) 你可以通过将现有路径拖放到目标形状层级中，来向任何形状添加新路径。</p></blockquote><h3 id="​-路径层属性-path-layer-properties" tabindex="-1"><a href="#path-layer-properties">​</a> 路径层属性 (Path layer properties) <a class="header-anchor" href="#​-路径层属性-path-layer-properties" aria-label="Permalink to &quot;[​](#path-layer-properties) 路径层属性 (Path layer properties)&quot;">​</a></h3><p>路径层会显示与该路径类型相关的属性。详细了解 <a href="/docs/editor/fundamentals/procedural-shapes">程序化形状 (Procedural Shapes)</a>。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 路径层属性)</p></blockquote><h2 id="​-enter-和-esc-快捷键" tabindex="-1"><a href="#enter-and-esc-shortcuts">​</a> Enter 和 Esc 快捷键 <a class="header-anchor" href="#​-enter-和-esc-快捷键" aria-label="Permalink to &quot;[​](#enter-and-esc-shortcuts) Enter 和 Esc 快捷键&quot;">​</a></h2><p>使用 <code>Enter</code> 键可以快速向下导航层级面板。如果你选中了一个形状，这允许你快速进入并选中子级路径层。 使用 <code>Esc</code> 键可以快速向上导航层级面板。如果你选中了一个路径，这允许你快速返回并选中父级形状层。</p><p><a href="/docs/editor/fundamentals/pen-tool-overview">钢笔工具概览 (Pen Tool Overview)</a><a href="/docs/editor/fundamentals/procedural-shapes">程序化形状 (Procedural Shapes)</a></p>',14)])])}const m=a(o,[["render",h]]);export{u as __pageData,m as default};
